import{_ as s,o as a,c as e,a2 as n}from"./chunks/framework.hwbV7reR.js";const r=JSON.parse('{"title":"Подключение своего backend","description":"","frontmatter":{},"headers":[],"relativePath":"integration.md","filePath":"integration.md","lastUpdated":1791654171000}'),t={name:"integration.md"};function o(h,i,p,l,d,k){return a(),e("div",null,[...i[0]||(i[0]=[n(`<h1 id="подключение-своего-backend" tabindex="-1">Подключение своего backend <a class="header-anchor" href="#подключение-своего-backend" aria-label="Permalink to &quot;Подключение своего backend&quot;">​</a></h1><p>Backend отвечает за авторизацию, право на доступ, срок и свободный слот. Он создаёт стабильный <code>device_id</code> и сохраняет ответный <code>connection_id</code>. Оркестратор не проверяет пользовательские пароли и не является публичным API для приложения.</p><p>Нужны запущенный оркестратор и хотя бы один совместимый активный узел. Тесты репозитория работают без узла; приведённая ниже последовательность — реальные операции над доступом. Используйте отдельное тестовое устройство и отзовите его после проверки. Ключ backend читайте из приватного файла и добавляйте в <code>Authorization: Bearer …</code>; не передавайте его в командной строке или клиенте. Для удалённого backend обязателен HTTPS, локально допустим loopback HTTP.</p><h2 id="_1-узнать-возможности" tabindex="-1">1. Узнать возможности <a class="header-anchor" href="#_1-узнать-возможности" aria-label="Permalink to &quot;1. Узнать возможности&quot;">​</a></h2><p><code>GET /internal/v2/capabilities</code> возвращает доступные <code>protocols</code> и <code>export_formats</code>. Выбирайте только протоколы, поддерживаемые и вашим VPN-клиентом, и сервисом. Наличие TrustTunnel в модели данных не означает наличия рабочего драйвера.</p><h2 id="_2-создать-назначение" tabindex="-1">2. Создать назначение <a class="header-anchor" href="#_2-создать-назначение" aria-label="Permalink to &quot;2. Создать назначение&quot;">​</a></h2><p><code>POST /internal/v2/connections</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schema_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;device_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;device-example-01&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Test device&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expires_at&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2027-01-01T00:00:00.000Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;capabilities&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;protocol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;amneziawg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;configuration_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Дата приведена для примера: при реальном запросе передайте будущий оплаченный или разрешённый срок. Ответ <code>Connection</code> содержит <code>connection_id</code>, <code>device_id</code>, <code>node_id</code>, <code>protocol</code>, <code>state</code>, <code>expires_at</code> и <code>schema_version</code>. Сохраните идентификаторы до следующего шага. Только <code>active</code> допускает использование доступа; после ответа создания запросите конфигурацию с повторной проверкой состояния.</p><p>Если ответ потерян, повторите <strong>тот же запрос для того же device_id</strong>. Не создавайте новое устройство и не меняйте срок в повторе первоначального запроса. Продление — отдельная операция. Назначение не создаётся заново при каждом нажатии «Подключиться».</p><h2 id="_3-получить-параметры-туннеля" tabindex="-1">3. Получить параметры туннеля <a class="header-anchor" href="#_3-получить-параметры-туннеля" aria-label="Permalink to &quot;3. Получить параметры туннеля&quot;">​</a></h2><p><code>POST /internal/v2/connections/{connection_id}/configuration</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schema_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;device_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;device-example-01&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;capabilities&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;protocol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;amneziawg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;configuration_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Ответ содержит <code>revision</code> и <code>configuration</code> с полями <code>protocol</code>, <code>version</code>, <code>format</code>, <code>data</code>. Передайте данные соответствующему VPN-движку. Это секретный ответ: не записывайте его в журналы, аналитику, публичный кэш или диагностический экспорт. Ответ API подтверждает выдачу параметров, а не установление туннеля на устройстве.</p><p>Для стороннего клиента используйте <code>POST …/{connection_id}/export</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;schema_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;device_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;device-example-01&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;format&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;conf&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>document</code> задаёт расширение, MIME-тип, кодировку и содержимое. QR возвращается как PNG в base64. Файл — снимок параметров; после переноса на другой сервер его может потребоваться импортировать снова. Формат выбирает драйвер оркестратора.</p><h2 id="_4-продлить-проверить-отозвать" tabindex="-1">4. Продлить, проверить, отозвать <a class="header-anchor" href="#_4-продлить-проверить-отозвать" aria-label="Permalink to &quot;4. Продлить, проверить, отозвать&quot;">​</a></h2><p><code>POST …/{connection_id}/renew</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;device_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;device-example-01&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expires_at&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2027-02-01T00:00:00.000Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;idempotency_key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;renewal-example-01&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Сохраните ключ операции до отправки. При потере ответа повторяйте прежний ключ и тело; новый ключ предназначен для нового действия, не для сетевого повтора.</p><p><code>GET …/{connection_id}?device_id=device-example-01</code> проверяет состояние. <code>POST …/{connection_id}/disable</code> с <code>{&quot;device_id&quot;:&quot;device-example-01&quot;}</code> отзывает доступ. Таймаут отзыва не является подтверждением его завершения: повторите операцию и проверьте состояние. <code>enable</code> не продлевает срок и не выдаёт новую оплату.</p><h2 id="_5-восстановление" tabindex="-1">5. Восстановление <a class="header-anchor" href="#_5-восстановление" aria-label="Permalink to &quot;5. Восстановление&quot;">​</a></h2><p>Передавайте в <code>POST …/{connection_id}/recover</code> прежнюю <code>expected_revision</code> вместе с телом запроса конфигурации. Повтор той же ревизии не должен запускать новое переключение. Сохраните новую ревизию успешного ответа.</p><p>Единичный сбой сайта не доказывает неисправность VPN. Клиент должен отличать отсутствие сети, недоступность отдельного ресурса и проблему туннеля до recovery. При <code>503 lease_waiting</code> продолжается безопасное ожидание отзыва; при <code>429 recovery_cooldown</code> нужно выдержать настроенную паузу. Не запускайте бесконечный цикл и не создавайте новый device_id для обхода этих состояний.</p><p>Политика повторов: <a href="./errors.html">ошибки</a>. Формальные тела и ответы: <a href="https://github.com/UndercoreCo/orchestrator/blob/main/contracts/openapi.json" target="_blank" rel="noreferrer">OpenAPI</a>. Совместимые маршруты v1 описаны отдельно в <a href="./api.html">API</a>; новым интеграциям они не нужны.</p>`,26)])])}const E=s(t,[["render",o]]);export{r as __pageData,E as default};
